                // Top wall (n)
                if (cell.n && r > 0) ctx.moveTo(x1, y1); ctx.lineTo(x1 + cs, y1);
                // Right wall (e)
                if (cell.e && c < this.size.cols - 1) ctx.moveTo(x1 + cs, y1); ctx.lineTo(x1 + cs, y1 + cs);
                // Bottom wall (s)
                if (cell.s && r < this.size.rows - 1) ctx.moveTo(x1, y1 + cs); ctx.lineTo(x1 + cs, y1 + cs);
                // Left wall (w)
                if (cell.w && c > 0) ctx.moveTo(x1, y1); ctx.lineTo(x1, y1 + cs);
            }
        }
        ctx.stroke();

        // Draw Spawn & Exit markers
        if (this.spawn) {
            const sx = offsetX + this.spawn.c * cs + cs/2;
            const sy = offsetY + this.spawn.r * cs + cs/2;
            ctx.fillStyle = 'rgba(0, 120, 0, 0.3)';
            ctx.beginPath(); ctx.arc(sx, sy, cs/4, 0, Math.PI*2); ctx.fill();
        }

        const ex = offsetX + this.exit.c * cs + cs/2;
        const ey = offsetY + this.exit.r * cs + cs/2;
        ctx.fillStyle = '#e74c3c';
        ctx.beginPath(); ctx.arc(ex, ey, cs/2, 0, Math.PI*2); ctx.fill();

        // Draw Bots
        for (let b of this.bots) {
            if (b.finished) continue;

            const bx = offsetX + b.pos.c * cs + cs/2;
            const by = offsetY + b.pos.r * cs + cs/2;

            ctx.fillStyle = b.color;
            // Smooth movement interpolation logic is implicit if we draw at exact center?
            // To make it "smoothly", I'll just use `pos` directly but maybe shift slightly if needed?
            // Prompt: "SMOOTHLY (interpolated between cells, not teleporting)".
            // Since `tick` advances grid pos, simple drawing at `pos` is discrete.
            // I will add a small visual offset or simply accept that discrete steps look fine for this context unless it's super high speed.
            // But let's implement simple lerp to previous position? 
            // For simplicity in this constraint, standard "dot" at center works if we move 1 cell per tick? No.
            // Let's add a visual delay or offset.

