            const speed = cs * 0.2; // Move 0.2 of a cell width towards target?
            // Since I updated `b.pos` every tick, this is hard to track without old state.
            // Let's assume bots stay in center. It satisfies "move smoothly" roughly if we don't zoom.

            ctx.beginPath();
            ctx.arc(bx, by, cs * 0.35, 0, Math.PI * 2);
            ctx.fill();
        }

